describe('Task Deletion with Confirmation Dialog', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should delete a task with confirmation dialog and update task list', () => {
    // Verify initial task list
    cy.get('[data-testid="task-list"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('have.length.greaterThan', 0);

    // Intercept delete API call
    cy.intercept('DELETE', '/api/tasks/*').as('deleteTask');

    // Click on a task to delete
    cy.get('[data-testid="task-item-1"]').click();

    // Verify confirmation dialog appears
    cy.get('[data-testid="confirm-delete-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-button"]').should('be.visible');

    // Verify confirm button is enabled
    cy.get('[data-testid="confirm-delete-button"]').should('be.enabled');

    // Click confirm button
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Task deleted successfully');

    // Verify task is removed from list
    cy.get('[data-testid="task-item-1"]').should('not.exist');

    // Verify API call was made
    cy.wait('@deleteTask').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should not delete a task when confirmation dialog is cancelled', () => {
    // Verify initial task list
    cy.get('[data-testid="task-list"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('have.length.greaterThan', 0);

    // Intercept delete API call
    cy.intercept('DELETE', '/api/tasks/*').as('deleteTask');

    // Click on a task to delete
    cy.get('[data-testid="task-item-2"]').click();

    // Verify confirmation dialog appears
    cy.get('[data-testid="confirm-delete-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-button"]').should('be.visible');

    // Click cancel button
    cy.get('[data-testid="cancel-delete-button"]').click();

    // Verify confirmation dialog closes
    cy.get('[data-testid="confirm-delete-dialog"]').should('not.exist');

    // Verify task remains in list
    cy.get('[data-testid="task-item-2"]').should('be.visible');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify API call was not made
    cy.wait('@deleteTask').then((interception) => {
      expect(interception.request.method).to.equal('DELETE');
      expect(interception.response.statusCode).to.equal(200);
    });
  });
});
